// Offline support + automatic updates.
//
// Our service worker (sw.js, generated by tool/build_web.py) caches the
// whole app after the first visit. Every time the app is opened or brought
// back to the foreground it asks the server for a newer version. When one
// has been installed:
//   - during the first seconds after launch -> reload right away;
//   - later -> reload the next time the user returns to the app, so nothing
//     typed or counted is interrupted (the app saves its state when hidden).
(function () {
  if (!('serviceWorker' in navigator)) return;

  var hadController = !!navigator.serviceWorker.controller;
  var startedAt = Date.now();
  var updateReady = false;
  var reloading = false;

  function reload() {
    if (reloading) return;
    reloading = true;
    try { sessionStorage.setItem('qazohisob-updated', '1'); } catch (e) {}
    location.reload();
  }

  navigator.serviceWorker.addEventListener('controllerchange', function () {
    // First install: the page is already the current version.
    if (!hadController) { hadController = true; return; }
    if (Date.now() - startedAt < 15000) reload();
    else updateReady = true;
  });

  navigator.serviceWorker.register('sw.js').then(function (registration) {
    document.addEventListener('visibilitychange', function () {
      if (document.visibilityState !== 'visible') return;
      if (updateReady) { reload(); return; }
      registration.update().catch(function () {});
    });
  }).catch(function (e) {
    console.warn('Service worker registration failed', e);
  });
})();

// Ask the browser to keep the database even when storage is low.
if (navigator.storage && navigator.storage.persist) {
  navigator.storage.persist();
}

function showUpdatedNotice() {
  var updated = false;
  try {
    updated = sessionStorage.getItem('qazohisob-updated') === '1';
    sessionStorage.removeItem('qazohisob-updated');
  } catch (e) {}
  if (!updated) return;
  var note = document.createElement('div');
  note.id = 'update-notice';
  note.textContent = 'Ilova yangilandi ✓';
  note.style.cssText = 'position:fixed;left:50%;bottom:96px;transform:translateX(-50%);' +
    'background:#103D32;color:#fff;padding:10px 18px;border-radius:14px;' +
    'font:600 14px -apple-system,system-ui,sans-serif;z-index:10;' +
    'box-shadow:0 6px 20px rgba(0,0,0,.2);transition:opacity .4s ease';
  document.body.appendChild(note);
  setTimeout(function () { note.style.opacity = '0'; }, 2600);
  setTimeout(function () { note.remove(); }, 3100);
}

_flutter.loader.load({
  onEntrypointLoaded: async function (engineInitializer) {
    const appRunner = await engineInitializer.initializeEngine();
    await appRunner.runApp();
    const splash = document.getElementById('splash');
    if (splash) {
      splash.style.opacity = '0';
      setTimeout(function () { splash.remove(); }, 300);
    }
    showUpdatedNotice();
  },
});
